const test = require('node:test');
const assert = require('node:assert/strict');
const { approvedPage } = require('../review.cjs');
const reports = Object.freeze([
  Object.freeze({id:'r1',status:'draft'}),
  Object.freeze({id:'r2',status:'approved'}),
  Object.freeze({id:'r3',status:'approved'}),
  Object.freeze({id:'r4',status:'rejected'}),
  Object.freeze({id:'r5',status:'approved'})
]);
const ids = rows => rows.map(row => row.id);
test('offset applies to the filtered sequence', () => {
  assert.deepEqual(ids(approvedPage(reports, 0, 2)), ['r2','r3']);
  assert.deepEqual(ids(approvedPage(reports, 1, 2)), ['r3','r5']);
  assert.deepEqual(ids(approvedPage(reports, 2, 2)), ['r5']);
  assert.deepEqual(approvedPage(reports, 3, 2), []);
});
test('empty pages and exact status matching', () => {
  assert.deepEqual(approvedPage(reports, 1, 0), []);
  assert.deepEqual(approvedPage([], 0, 2), []);
  assert.deepEqual(approvedPage([{id:'r6',status:'Approved'}], 0, 2), []);
  assert.equal(reports.length, 5);
});

test('returns complete records without changing mutable input', () => {
  const input = [
    {id:'p1',status:'draft',title:'Outline'},
    {id:'p2',status:'approved',title:'Opening',meta:{owner:'Lin'}},
    {id:'p3',status:'approved',title:'Closing',meta:{owner:'Mei'}}
  ];
  const before = structuredClone(input);
  const result = approvedPage(input, 0, 2);
  assert.deepEqual(result, [before[1],before[2]]);
  assert.deepEqual(input, before);
  assert.notStrictEqual(result, input);
});

